 public static void Build(){EditorSceneManager.SaveOpenScenes();var scene=EditorSceneManager.OpenScene(T,OpenSceneMode.Single);string backup=B+"References/Teatro_Antes_Entorno.unity";if(!File.Exists(backup))AssetDatabase.CopyAsset(T,backup);var old=scene.GetRootGameObjects().FirstOrDefault(g=>g.name=="Entorno_Urbano_Graca_Aranha");if(old)UnityEngine.Object.DestroyImmediate(old);root=new GameObject("Entorno_Urbano_Graca_Aranha").transform;meshNumber=0;
 concrete=Mat("Concreto_claro",new Color(.62f,.62f,.58f),.15f);limestone=Mat("Pedra_bege",new Color(.70f,.67f,.58f),.18f);glass=Mat("Vidro_azul_cinza",new Color(.19f,.29f,.34f),.72f,.15f);metal=Mat("Aluminio_grafite",new Color(.19f,.20f,.21f),.42f,.45f);asphalt=Mat("Asfalto",new Color(.2f,.21f,.22f),.05f);pavement=Mat("Calcada_pedra_portuguesa",Color.white,.1f);pavement.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/Teatro_Centro_SESI/Textures/Calcada_portuguesa.png");white=Mat("Sinalizacao_branca",new Color(.83f,.82f,.75f),.1f);green=Mat("Folhagem",new Color(.17f,.27f,.12f),.05f);yellow=Mat("Taxi_amarelo",new Color(.85f,.59f,.035f),.42f);black=Mat("Borracha",new Color(.035f,.04f,.04f),.1f);Texture(asphalt,"Asfalto_ruido",new Color(.40f,.41f,.42f),new Color(.65f,.66f,.67f),50);Texture(concrete,"Concreto_ruido",new Color(.78f,.77f,.73f),Color.white,16);
