 static Material Mat(string n,Color c,float smooth,float metallic=0){string p=B+"Materials/"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,p);}m.color=c;m.SetFloat("_Smoothness",smooth);m.SetFloat("_Metallic",metallic);m.enableInstancing=true;return m;}
 static void Texture(Material m,string name,Color a,Color b,float frequency){string p=B+"Textures/"+name+".png";if(!File.Exists(p)){var t=new Texture2D(256,256);for(int y=0;y<256;y++)for(int x=0;x<256;x++)t.SetPixel(x,y,Color.Lerp(a,b,Mathf.PerlinNoise(x*.173f,y*.173f)));t.Apply();File.WriteAllBytes(p,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);AssetDatabase.ImportAsset(p);}m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(p);m.mainTextureScale=Vector2.one;}
 static Transform Group(string n,Transform p=null){var t=new GameObject(n).transform;t.SetParent(p?p:root,false);return t;}
