 static Mesh SaveMesh(string n,Mesh mesh){mesh.name=n;mesh.RecalculateNormals();mesh.RecalculateBounds();string p=B+"Models/"+n+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(p);if(old){EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);return old;}AssetDatabase.CreateAsset(mesh,p);return mesh;}
 public class Batch {public List<Vector3> v=new List<Vector3>();public List<int> tr=new List<int>();public List<Vector2> uv=new List<Vector2>();
 public void Quad(Vector3 a,Vector3 b,Vector3 c,Vector3 d,float u=1,float w=1){int i=v.Count;v.AddRange(new[]{a,b,c,d});uv.AddRange(new[]{Vector2.zero,new Vector2(u,0),new Vector2(u,w),new Vector2(0,w)});tr.AddRange(new[]{i,i+1,i+2,i,i+2,i+3});}
 public void Cube(Vector3 p,Vector3 size){Vector3 h=size/2;var a=p-h;var b=p+h;Quad(new Vector3(a.x,a.y,a.z),new Vector3(a.x,b.y,a.z),new Vector3(b.x,b.y,a.z),new Vector3(b.x,a.y,a.z));Quad(new Vector3(b.x,a.y,b.z),new Vector3(b.x,b.y,b.z),new Vector3(a.x,b.y,b.z),new Vector3(a.x,a.y,b.z));Quad(new Vector3(a.x,a.y,b.z),new Vector3(a.x,b.y,b.z),new Vector3(a.x,b.y,a.z),new Vector3(a.x,a.y,a.z));Quad(new Vector3(b.x,a.y,a.z),new Vector3(b.x,b.y,a.z),new Vector3(b.x,b.y,b.z),new Vector3(b.x,a.y,b.z));Quad(new Vector3(a.x,b.y,a.z),new Vector3(a.x,b.y,b.z),new Vector3(b.x,b.y,b.z),new Vector3(b.x,b.y,a.z));Quad(new Vector3(a.x,a.y,b.z),new Vector3(a.x,a.y,a.z),new Vector3(b.x,a.y,a.z),new Vector3(b.x,a.y,b.z));}
 public Mesh Mesh(){var m=new Mesh();m.indexFormat=IndexFormat.UInt32;m.SetVertices(v);m.SetTriangles(tr,0);m.SetUVs(0,uv);return m;}}
 static GameObject Finish(Batch batch,string n,Material mat,Transform p,bool collider=false){var g=new GameObject(n);g.transform.SetParent(p,false);g.AddComponent<MeshFilter>().sharedMesh=SaveMesh(n,batch.Mesh());g.AddComponent<MeshRenderer>().sharedMaterial=mat;g.isStatic=true;if(collider)g.AddComponent<MeshCollider>().sharedMesh=g.GetComponent<MeshFilter>().sharedMesh;return g;}
 static float Distance(Vector3 p,Vector3 a,Vector3 b){var d=b-a;float t=Mathf.Clamp01(Vector3.Dot(p-a,d)/Mathf.Max(.001f,d.sqrMagnitude));return Vector3.Distance(p,a+d*t);}
 static void Terrain(Layout l){var g=Group("Ruas_calcadas_meios_fios");var road=new Batch();var sidewalk=new Batch();var neutral=new Batch();var curb=new Batch();const int step=2;const int nx=200,nz=185;var cells=new bool[nx,nz];
 for(int ix=0;ix<nx;ix++)for(int iz=0;iz<nz;iz++){int x=-180+ix*step,z=-220+iz*step;Vector3 p=new Vector3(x+1,0,z+1);float margin=999;foreach(var r in l.roads)for(int i=1;i<r.points.Length;i++)margin=Mathf.Min(margin,Distance(p,r.points[i-1].V,r.points[i].V)-r.width/2);bool street=margin<0;cells[ix,iz]=street;float y=street?-.19f:-.025f;var b=street?road:margin<5?sidewalk:neutral;b.Quad(new Vector3(x,y,z),new Vector3(x,y,z+step),new Vector3(x+step,y,z+step),new Vector3(x+step,y,z),1,1);int n=b.uv.Count;float scale=street?.45f:.12f;b.uv[n-4]=new Vector2(x*scale,z*scale);b.uv[n-3]=new Vector2(x*scale,(z+step)*scale);b.uv[n-2]=new Vector2((x+step)*scale,(z+step)*scale);b.uv[n-1]=new Vector2((x+step)*scale,z*scale);}
 for(int ix=1;ix<nx-1;ix++)for(int iz=1;iz<nz-1;iz++){if(!cells[ix,iz])continue;float x=-180+ix*step,z=-220+iz*step;if(!cells[ix-1,iz])curb.Quad(new Vector3(x,-.19f,z),new Vector3(x,-.025f,z),new Vector3(x,-.025f,z+step),new Vector3(x,-.19f,z+step));if(!cells[ix+1,iz])curb.Quad(new Vector3(x+step,-.19f,z+step),new Vector3(x+step,-.025f,z+step),new Vector3(x+step,-.025f,z),new Vector3(x+step,-.19f,z));if(!cells[ix,iz-1])curb.Quad(new Vector3(x+step,-.19f,z),new Vector3(x+step,-.025f,z),new Vector3(x,-.025f,z),new Vector3(x,-.19f,z));if(!cells[ix,iz+1])curb.Quad(new Vector3(x,-.19f,z+step),new Vector3(x,-.025f,z+step),new Vector3(x+step,-.025f,z+step),new Vector3(x+step,-.19f,z+step));}
 Finish(road,"Malha_ruas_asfalto",asphalt,g,true);Finish(sidewalk,"Malha_calcadas",pavement,g,true);Finish(neutral,"Malha_lotes_neutros",concrete,g,true);Finish(curb,"Meios_fios_continuos",limestone,g);Box("Subsolo continuo",new Vector3(20,-.5f,-35),new Vector3(400,.5f,370),concrete,g);
 for(int i=0;i<7;i++)Box("Faixa pedestre",new Vector3(-14+i*.65f,-.175f,-41),new Vector3(.4f,.018f,12),white,g,false);for(int x=-140;x<190;x+=9)Box("Linha viária descontínua",new Vector3(x,-.172f,-41),new Vector3(3,.012f,.11f),white,g,false);
