 static Vector3[] Polygon(Building b){var p=b.polygon.Select(q=>q.V-new Vector3(b.x,0,b.z)).ToList();if(Vector3.Distance(p[0],p[p.Count-1])<.01f)p.RemoveAt(p.Count-1);float area=0;for(int i=0;i<p.Count;i++){var a=p[i];var c=p[(i+1)%p.Count];area+=a.x*c.z-c.x*a.z;}if(area<0)p.Reverse();return p.ToArray();}
 static void Extrude(Batch batch,Vector3[] p,float low,float high){for(int i=0;i<p.Length;i++){var a=p[i];var b=p[(i+1)%p.Length];batch.Quad(a+Vector3.up*low,a+Vector3.up*high,b+Vector3.up*high,b+Vector3.up*low);} // Roof: ear-clipping for concave footprints.
 var ids=Enumerable.Range(0,p.Length).ToList();int safety=0;while(ids.Count>2&&safety++<p.Length*p.Length){bool found=false;for(int j=0;j<ids.Count;j++){int a=ids[(j+ids.Count-1)%ids.Count],b=ids[j],c=ids[(j+1)%ids.Count];var ab=p[b]-p[a];var bc=p[c]-p[b];if(ab.x*bc.z-ab.z*bc.x<=.0001f)continue;bool inside=false;foreach(int k in ids){if(k==a||k==b||k==c)continue;var q=p[k];float s1=(p[b].x-p[a].x)*(q.z-p[a].z)-(p[b].z-p[a].z)*(q.x-p[a].x),s2=(p[c].x-p[b].x)*(q.z-p[b].z)-(p[c].z-p[b].z)*(q.x-p[b].x),s3=(p[a].x-p[c].x)*(q.z-p[c].z)-(p[a].z-p[c].z)*(q.x-p[c].x);if(s1>=0&&s2>=0&&s3>=0){inside=true;break;}}if(inside)continue;int start=batch.v.Count;batch.v.AddRange(new[]{p[a]+Vector3.up*high,p[c]+Vector3.up*high,p[b]+Vector3.up*high});batch.uv.AddRange(new[]{Vector2.zero,Vector2.up,Vector2.right});batch.tr.AddRange(new[]{start,start+1,start+2});ids.RemoveAt(j);found=true;break;}if(!found)break;}}
 static void CreateBuilding(Building b){var g=Group(b.id+"_"+b.name);g.position=new Vector3(b.x,0,b.z);var data=g.gameObject.AddComponent<UrbanBuilding>();data.sourceId=b.id;data.facadeEstimated=b.style=="cream"||b.style=="tower";data.reference="OSM: implantação/altura indicativa; fotografias Firjan, Teixeira Duarte, Colliers e ABL; faces não documentadas estimadas.";var poly=Polygon(b);float height=b.height;var body=new Batch();if(b.style=="capanema"){Extrude(body,poly,0,5);poly=new[]{new Vector3(-b.width*.42f,0,-b.depth*.16f),new Vector3(b.width*.42f,0,-b.depth*.16f),new Vector3(b.width*.42f,0,b.depth*.16f),new Vector3(-b.width*.42f,0,b.depth*.16f)};Extrude(body,poly,6,58);height=58;for(int i=0;i<10;i++)body.Cube(new Vector3(-b.width*.38f+i*b.width*.084f,3,-b.depth*.10f),new Vector3(.65f,6,.65f));}else if(b.id=="1228853764"){Extrude(body,poly,0,5);poly=new[]{new Vector3(-13,0,-14),new Vector3(13,0,-14),new Vector3(13,0,14),new Vector3(-13,0,14)};Extrude(body,poly,5,height);}else Extrude(body,poly,0,height);
 var solid=Finish(body,"Corpo_"+b.id,b.style=="maua"?metal:limestone,g,true);var lods=new List<LOD>();for(int lod=0;lod<2;lod++){var detail=Group("LOD"+lod,g);var windows=new Batch();var trim=new Batch();float floor=b.style=="classic"?5:3.25f;for(int edge=0;edge<poly.Length;edge++){var a=poly[edge];var end=poly[(edge+1)%poly.Length];var delta=end-a;float length=delta.magnitude;if(length<1)continue;Vector3 along=delta.normalized,outward=new Vector3(along.z,0,-along.x);int cols=Mathf.Max(1,Mathf.FloorToInt(length/(b.style=="classic"?4:2.5f)));float bay=length/cols;for(float y=4.3f;y<height-2;y+=floor*(lod==0?1:2)){for(int c=0;c<cols;c++){float w=bay*(b.style=="maua"?.95f:.68f);var center=a+along*(c+.5f)*bay+outward*.045f+Vector3.up*y;float hh=b.style=="classic"?2.7f:1.9f;windows.Quad(center-along*w/2-Vector3.up*hh/2,center-along*w/2+Vector3.up*hh/2,center+along*w/2+Vector3.up*hh/2,center+along*w/2-Vector3.up*hh/2);if(lod==0){var sill=center-Vector3.up*(hh/2+.06f);OrientedBox(trim,sill,along,outward,w+.18f,.12f,.22f);if(b.style=="classic")OrientedBox(trim,center+Vector3.up*(hh/2+.13f),along,outward,w+.32f,.18f,.24f);}}
 if(b.style=="tower"||b.style=="capanema")OrientedBox(trim,a+delta/2+Vector3.up*(y+1.25f)+outward*.1f,along,outward,length,.16f,.25f);}
 if(b.style=="maua"&&lod==0)for(float d=.3f;d<length;d+=.5f)OrientedBox(trim,a+along*d+outward*.18f+Vector3.up*(height/2),along,outward,.065f,height-1,.4f);
 if(b.style=="cream"&&lod==0)for(int col=0;col<=cols;col++)OrientedBox(trim,a+along*col*bay+outward*.06f+Vector3.up*height/2,along,outward,.12f,height,.15f);
 if(b.style=="classic")foreach(float y in new[]{.35f,1,7.3f,height-.5f})OrientedBox(trim,a+delta/2+outward*.18f+Vector3.up*y,along,outward,length+.25f,.28f,.4f);
 }
 var wgo=Finish(windows,"Janelas_"+b.id+"_L"+lod,glass,detail);var tgo=Finish(trim,"Detalhes_"+b.id+"_L"+lod,b.style=="maua"?concrete:limestone,detail);lods.Add(new LOD(lod==0?.20f:.001f,new Renderer[]{solid.GetComponent<Renderer>(),wgo.GetComponent<Renderer>(),tgo.GetComponent<Renderer>()}));}
 var lg=g.gameObject.AddComponent<LODGroup>();lg.SetLODs(lods.ToArray());lg.RecalculateBounds();PrefabUtility.SaveAsPrefabAsset(g.gameObject,B+"Prefabs/Edificio_"+b.id+".prefab");}
 static void OrientedBox(Batch b,Vector3 p,Vector3 along,Vector3 normal,float w,float h,float depth){var a=along*w/2;var v=Vector3.up*h/2;var n=normal*depth/2;b.Quad(p-a-v+n,p-a+v+n,p+a+v+n,p+a-v+n);b.Quad(p+a-v-n,p+a+v-n,p-a+v-n,p-a-v-n);b.Quad(p-a+v+n,p-a+v-n,p+a+v-n,p+a+v+n);b.Quad(p-a-v-n,p-a-v+n,p+a-v+n,p+a-v-n);b.Quad(p-a-v-n,p-a+v-n,p-a+v+n,p-a-v+n);b.Quad(p+a-v+n,p+a+v+n,p+a+v-n,p+a-v-n);}
