 static void SetupSky(UnityEngine.SceneManagement.Scene scene){var imp=AssetImporter.GetAtPath(B+"Textures/Ceu_Diurno_PolyHaven_2k.hdr") as TextureImporter;imp.textureShape=TextureImporterShape.Texture2D;imp.sRGBTexture=false;imp.mipmapEnabled=false;imp.maxTextureSize=2048;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.SaveAndReimport();string p=B+"Lighting/Ceu_Diurno_PolyHaven.mat";var sky=AssetDatabase.LoadAssetAtPath<Material>(p);if(!sky){sky=new Material(Shader.Find("Skybox/Panoramic"));AssetDatabase.CreateAsset(sky,p);}sky.SetTexture("_MainTex",AssetDatabase.LoadAssetAtPath<Texture2D>(B+"Textures/Ceu_Diurno_PolyHaven_2k.hdr"));sky.SetFloat("_Exposure",.85f);sky.SetFloat("_Rotation",110);sky.SetFloat("_Mapping",1);sky.SetFloat("_ImageType",0);var sun=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Light>(true)).FirstOrDefault(l=>l.name=="Luz externa da fachada");if(!sun){var go=new GameObject("Sol_Entorno");go.transform.SetParent(root);sun=go.AddComponent<Light>();sun.type=LightType.Directional;}sun.transform.rotation=Quaternion.Euler(48,35,0);sun.color=new Color(1,.96f,.88f);sun.intensity=1.15f;sun.shadows=LightShadows.Soft;sun.shadowStrength=.8f;var settings=root.gameObject.AddComponent<UrbanDaylight>();settings.skybox=sky;settings.sun=sun;settings.Apply();foreach(var c in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true))){c.clearFlags=CameraClearFlags.Skybox;c.farClipPlane=650;}root.gameObject.AddComponent<UrbanRuntimeAudit>();DynamicGI.UpdateEnvironment();}
